"""Create the governed, label-isolated VDT delivery request and acceptance packet."""
from __future__ import annotations

import hashlib
import json
import os
import sys
from pathlib import Path
from typing import Any

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "tools"))
OUT = ROOT / "experiments/archive/v3_vdt_data_acquisition_request_20260925"
VDT = ROOT.parent / "VDT"
from validate_vdt_delivery import validate


def sha(path: Path) -> str: return hashlib.sha256(path.read_bytes()).hexdigest()
def write(name: str, value: Any) -> None:
    path = OUT / name; path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(value if isinstance(value, str) else json.dumps(value, indent=2, sort_keys=True) + "\n", encoding="utf-8")


def requirement(*, required: bool, current: str, blocker: str, fields: list[str], temporal: str, identity: str, provenance: str, leakage: str) -> dict[str, Any]:
    return {"required": required, "preferred": not required, "current_status": current, "blocking_reason": blocker, "required_fields": fields, "temporal_requirement": temporal, "identity_requirement": identity, "provenance_requirement": provenance, "label_leakage_risk": leakage}


def main() -> None:
    if (OUT / "MANIFEST.json").exists() and os.environ.get("CDOI_VDT_DATA_REQUEST_REBUILD_BEFORE_FREEZE") != "1":
        raise SystemExit("REFUSE_TO_OVERWRITE_VDT_DATA_REQUEST_ARCHIVE")
    OUT.mkdir(parents=True, exist_ok=True)
    source = validate(VDT)
    write("PREREGISTRATION.json", {"schema_version": "vdt_data_acquisition_request_v1", "scope": "governed data request and label-free acceptance design", "source": "EXTERNAL_READ_ONLY_VDT", "forbidden": ["current VDT modification", "label values in CDOI evidence", "window expansion", "RCA evaluation", "synthetic telemetry"]})
    write("VDT_CURRENT_BLOCKERS.json", {"schema_version": "vdt_current_blockers_v1", "temporal": "Valid incident windows end by 2026-09-05; current logs begin 2026-09-10.", "incident_windows": "63 of 100 source incident rows lack an end timestamp; one lacks service identity.", "modalities": ["metrics absent", "traces absent", "changes/deployments absent"], "labels": "rca_status is AI automation availability, not a governed root-cause label.", "provenance": "owner, collection, label creation, and independence unknown.", "source_hashes": source.get("source_hashes")})
    write("CURRENT_DELIVERY_LABEL_FREE_CHECK.json", source)
    requirements = {
        "incident_windows": requirement(required=True, current="INSUFFICIENT", blocker="63 missing end timestamps", fields=["incident_id", "incident_start", "incident_end", "affected_service_or_component", "environment", "declaration_source"], temporal="For each supplied incident, provide declared start/end and document open/unresolved representation; do not infer end locally.", identity="Affected service/component must map by authoritative exact ID.", provenance="Source system and export/filter rules required.", leakage="NONE"),
        "logs_events": requirement(required=True, current="TEMPORALLY_UNALIGNED", blocker="Current logs are Sep 10-11 while valid incidents end Sep 5", fields=["event_id", "timestamp", "service_or_application_id", "instance_or_host_if_available", "event_type", "severity", "message_or_event_code", "source_system", "environment"], temporal="Bounded pre-incident, incident, and post-incident evidence for actual supplied valid windows; delivery must demonstrate overlap.", identity="Exact service/application mapping required.", provenance="Collection period, source, sampling/drop behavior, and known gaps required.", leakage="LOW unless event content embeds post-resolution RCA fields; identify and exclude such fields."),
        "metrics": requirement(required=False, current="ABSENT", blocker="No current metric data", fields=["timestamp", "service_or_entity_id", "metric_name", "value", "unit", "metric_kind", "aggregation", "sampling_interval", "labels_dimensions", "source_system"], temporal="Aligned to incident windows; machine-readable series preferred over dashboards.", identity="Authoritative entity label mapping required.", provenance="Instrumentation/source and aggregation semantics required.", leakage="LOW; identify derived RCA annotations if present."),
        "traces": requirement(required=False, current="ABSENT", blocker="No current trace data", fields=["trace_id", "span_id", "parent_span_id", "service_or_entity_id", "start_timestamp", "end_timestamp", "duration", "status_or_error", "operation_name", "environment"], temporal="Spans must overlap supplied windows.", identity="Exact trace service-name mapping required.", provenance="Collector, sampling, retention, and missing-period documentation required.", leakage="LOW; trace path must not be pre-labeled causal."),
        "changes_deployments": requirement(required=False, current="ABSENT", blocker="No current change/deployment data", fields=["change_id", "service_or_entity_id", "timestamp", "change_type", "version_or_release", "environment", "deployment_status", "source"], temporal="Changes must be timestamped relative to valid windows; proximity remains non-causal.", identity="Exact deployed service identity required.", provenance="Change source and lifecycle semantics required.", leakage="MEDIUM if post-incident resolution fields are included; isolate them."),
        "root_cause_labels": requirement(required=True, current="NOT_AVAILABLE", blocker="rca_status is not a root-cause label", fields=["incident_id", "root_service_or_component_or_entity", "root_cause_category_or_fault_domain", "confirmed_cause", "label_version"], temporal="Labels are withheld from normalization/profile/Qwen input until a post-freeze evaluation join.", identity="Root target must map to stable CDOI entity IDs or authoritative map.", provenance="Creator, manual/automatic process, creation time, source, review status, corrections/version history, and whether created after resolution required.", leakage="HIGH: physically/logically isolate from all inference artifacts."),
        "collection_and_independence": requirement(required=True, current="UNKNOWN", blocker="No owner, collection, or independence documentation", fields=["data_owner", "source_systems", "collection_method", "collection_period", "export_date", "filtering_rules", "retention_policy", "sampling_drop_behavior", "known_missing_periods", "development_use_history"], temporal="Must identify snapshot periods and alignment basis.", identity="Provide authoritative mappings for service/application/instance/host/pod, metric labels, trace service names, and incident service fields.", provenance="Must demonstrate labels were not generated by CDOI/Qwen-under-test or candidate-generation logic and incident selection was not based on CDOI outcomes.", leakage="HIGH until governance review confirms isolation."),
    }
    write("VDT_DATA_ACQUISITION_REQUIREMENTS.json", {"schema_version": "vdt_data_acquisition_requirements_v1", "modalities": requirements, "minimum_viable_dataset": "No arbitrary incident N is claimed. Each included incident needs a valid authoritative window, exact affected-service identity, temporally overlapping logs/events, and a governed root target/category label withheld from inference. A multi-incident set with documented provenance is needed before comparative RCA conclusions.", "preferred_rich_dataset": "Across incidents, include logs/events plus available metrics, traces, changes/deployments, topology, authoritative identity mapping, governed labels, and provenance. Not every modality is required for every incident; absence must be explicit."})
    write("VDT_REQUIRED_LABEL_PROVENANCE.json", {"schema_version": "vdt_label_provenance_requirements_v1", "required": ["label creator/owner", "manual versus automated creation", "creation timestamp", "source system", "creation relative to resolution", "review/approval status", "whether derived from RCA automation", "whether derived from CDOI/Qwen-under-test", "correction/version history", "incident-selection independence from CDOI outcomes"], "acceptance": "Without these, VDT is integration/development data at most and not independent validation."})
    write("VDT_ACCEPTANCE_CHECKLIST.json", {"schema_version": "vdt_acceptance_checklist_v1", "automated": ["file hashes", "required-file/schema presence", "timezone-aware timestamp parsing", "valid incident windows", "incident/telemetry overlap", "per-incident evidence counts", "exact identity resolution", "duplicate detection", "modality coverage", "label-field-name detection without reading label values"], "governance_review": ["data ownership/collection provenance", "root-cause label semantics", "label provenance", "evaluation independence", "retention/access governance"], "reject_or_hold_conditions": ["no valid incident windows", "zero aligned telemetry overlap", "unresolved identity mapping", "labels presented to inference", "unknown label provenance for claimed validation"]})
    write("VDT_TEMPORAL_VALIDATION_SPEC.json", {"schema_version": "vdt_temporal_validation_spec_v1", "runner": "tools/validate_vdt_delivery.py", "reports": ["incident min/max", "telemetry min/max", "valid window count", "incident-event overlap count", "per-incident eligibility basis", "nearest before/after event distance when implemented for delivery review"], "policy": "Label-free; no artificial incident-window expansion or timestamp reinterpretation."})
    write("VDT_LABEL_ISOLATION_SPEC.json", {"schema_version": "vdt_label_isolation_spec_v1", "rule": "Potential RCA fields are detected by field name only and are not read into normalized evidence, candidate generation, CandidateEvidenceProfile construction, or Qwen input.", "current_enforcement": ["vdt_ingestion.load_incidents records rca_status as UNKNOWN_NOT_READ", "validate_vdt_delivery returns label field names only", "tests assert label value non-export"], "evaluation_join": "Only after an inference artifact freeze, authorized evaluation may join governed labels externally."})
    handoff = "# VDT Governed Data Handoff Request\n\n## Must have\n\n- Valid incident ID, start/end, affected service/component, environment, and declaration source.\n- Machine-readable events/logs overlapping each incident’s real window, with timestamp, stable ID, service/application ID, type/severity, source, and environment.\n- Authoritative service/application identity map.\n- Governed root service/component/entity or root-cause category labels, delivered separately from inference inputs.\n- Documentation for data ownership, collection/export period, filtering/missing data, label creation/review/versioning, and independence from CDOI/Qwen.\n\n## Should have\n\n- Metrics, traces, changes/deployments, and topology with the fields enumerated in `VDT_DATA_ACQUISITION_REQUIREMENTS.json`.\n\n## Optional\n\n- Instance/host/pod mappings and additional modality-specific context, where governed and available.\n\nCDOI will first run the supplied label-free acceptance checks. It will not infer missing windows, extrapolate telemetry, or use labels in candidate generation or model input.\n"
    write("VDT_DATA_HANDOFF_REQUEST.md", handoff)
    write("RESEARCH_GATE.json", {"schema_version": "vdt_data_request_gate_v1", "decisions": ["VDT_DATA_REQUEST_READY", "VDT_ALIGNED_DATA_REQUIRED", "VDT_GOVERNED_RCA_LABELS_REQUIRED", "VDT_PROVENANCE_REQUIRED"], "current_dataset_evaluation_authorized": False, "current_dataset_mutated": False})
    write("FINAL_REPORT.md", "# VDT Aligned-Data Acquisition Request\n\nThe current VDT files remain read-only and insufficient for RCA evaluation. This packet turns each evidence gap into a governed field, time-alignment, identity, provenance, and label-isolation requirement. It includes an automated label-free acceptance validator and does not set an arbitrary incident-count threshold.\n")
    files = sorted(path for path in OUT.rglob("*") if path.is_file() and path.name not in {"HASHES.json", "MANIFEST.json"}); write("HASHES.json", {"schema_version": "vdt_request_hashes_v1", "artifacts": {path.relative_to(OUT).as_posix(): sha(path) for path in files}})
    files = sorted(path for path in OUT.rglob("*") if path.is_file() and path.name != "MANIFEST.json"); write("MANIFEST.json", {"schema_version": "vdt_request_manifest_v1", "artifacts": {path.relative_to(OUT).as_posix(): sha(path) for path in files}})


if __name__ == "__main__": main()
